package com.pulsefit.member;
import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="members") public class Member { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String name; @Column(nullable=false,unique=true) private String email; private String phone; private LocalDate dateOfBirth; private String status="ACTIVE"; public Member(){} public Long getId(){return id;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
